import math

def control(obs):
    m=obs.get('local_map',{})
    def at(points,x):
        p=sorted((float(a),float(b)) for a,b in points)
        for i in range(len(p)-1):
            if p[i][0]<=x<=p[i+1][0] and p[i+1][0]-p[i][0]>0.01:
                f=(x-p[i][0])/(p[i+1][0]-p[i][0])
                return p[i][1]*(1-f)+p[i+1][1]*f
        return None
    left=m.get('left_rail',[])
    right=m.get('right_rail',[])
    centers=[]
    for x in (2.0,4.0,6.0,8.0):
        l=at(left,x); r=at(right,x)
        if l is not None and r is not None: centers.append((x,(l+r)/2))
    target=0.0
    if centers:
        x,c=min(centers,key=lambda z:abs(z[0]-6.0))
        target=math.degrees(math.atan2(c,x))
    hitch=obs.get('hitch_deg',0.0)
    desired=max(-22.0,min(22.0,1.5*target))
    steer=max(-40.0,min(40.0,2.2*(hitch-desired)))
    return (steer,-0.75)

