import math

def control(o):
    m=o['local_map']
    def interp(points,u):
        p=sorted(points)
        for i in range(len(p)-1):
            if p[i][0]<=u<=p[i+1][0] and p[i+1][0]-p[i][0]>0.01:
                a=(u-p[i][0])/(p[i+1][0]-p[i][0])
                return p[i][1]*(1-a)+p[i+1][1]*a
        return None
    targets=[]
    for u in (5,10,15):
        l=interp(m.get('left_rail',[]),u); r=interp(m.get('right_rail',[]),u)
        if l is not None and r is not None: targets.append((u,(l+r)/2))
    if targets:
        u,y=targets[-1]
        desired=max(-20,min(20,math.degrees(math.atan2(y,u))*1.4))
    else: desired=0
    h=o['hitch_deg']
    steer=max(-35,min(35,1.8*h-1.5*desired))
    speed=-1.0 if abs(h)<30 else -0.5
    return steer,speed,180

